import { readFile, writeFile, rename } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';

const DATA_FILE = process.env.BOOKS_FILE ?? new URL('./books.json', import.meta.url).pathname;

export async function loadBooks() {
  try {
    return JSON.parse(await readFile(DATA_FILE, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function saveBooks(books) {
  const tmp = DATA_FILE + '.tmp';
  await writeFile(tmp, JSON.stringify(books, null, 2) + '\n');
  await rename(tmp, DATA_FILE);
}

export async function addBook({ title, author, notes }) {
  const books = await loadBooks();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: (notes ?? '').trim(),
    finished: false,
    addedAt: new Date().toISOString(),
  };
  books.push(book);
  await saveBooks(books);
  return book;
}

export async function getBook(id) {
  const books = await loadBooks();
  return books.find((b) => b.id === id) ?? null;
}

export async function finishBook(id) {
  const books = await loadBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.finished = true;
  book.finishedAt = new Date().toISOString();
  await saveBooks(books);
  return book;
}

