import { createServer } from 'node:http';
import { loadBooks, addBook, getBook, finishBook } from './store.mjs';

const PORT = process.env.PORT ?? 3000;

const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const page = (title, body) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  :root { color-scheme: light dark; }
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; }
  h1 { font-size: 1.4rem; }
  h2 { font-size: 1.1rem; margin-top: 2rem; }
  ul { padding-left: 1.2rem; }
  li { margin: 0.4rem 0; }
  .author { opacity: 0.7; }
  form.inline { display: inline; }
  label { display: block; margin-top: 0.8rem; }
  input[type="text"], textarea { width: 100%; box-sizing: border-box; padding: 0.4rem; font: inherit; }
  button { margin-top: 0.8rem; padding: 0.3rem 0.9rem; font: inherit; cursor: pointer; }
  .notes { white-space: pre-wrap; border-left: 3px solid color-mix(in srgb, currentColor 30%, transparent); padding-left: 0.8rem; }
  .muted { opacity: 0.6; }
</style>
</head>
<body>
${body}
</body>
</html>`;

const bookItem = (b) => `<li>
  <a href="/book/${b.id}">${esc(b.title)}</a> <span class="author">by ${esc(b.author)}</span>
  ${b.finished ? '' : `<form class="inline" method="post" action="/book/${b.id}/finish"><button>Finished it</button></form>`}
</li>`;

function homePage(books) {
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  return page('My books', `
<h1>My books</h1>

<h2>Currently reading</h2>
${reading.length ? `<ul>${reading.map(bookItem).join('\n')}</ul>` : '<p class="muted">Nothing on the go right now.</p>'}

<h2>Finished</h2>
${finished.length ? `<ul>${finished.map(bookItem).join('\n')}</ul>` : '<p class="muted">Nothing finished yet.</p>'}

<h2>Add a book</h2>
<form method="post" action="/add">
  <label>Title <input type="text" name="title" required></label>
  <label>Author <input type="text" name="author" required></label>
  <label>Notes <textarea name="notes" rows="4"></textarea></label>
  <button>Add book</button>
</form>`);
}

function bookPage(b) {
  return page(b.title, `
<p><a href="/">&larr; All books</a></p>
<h1>${esc(b.title)}</h1>
<p class="author">by ${esc(b.author)}</p>
<p>${b.finished ? 'Finished' : `Currently reading
  <form class="inline" method="post" action="/book/${b.id}/finish"><button>Finished it</button></form>`}</p>
<h2>Notes</h2>
${b.notes ? `<div class="notes">${esc(b.notes)}</div>` : '<p class="muted">No notes yet.</p>'}`);
}

function send(res, status, html) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' });
  res.end(html);
}

function redirect(res, to) {
  res.writeHead(303, { location: to });
  res.end();
}

async function readForm(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 1e6) throw new Error('body too large');
  }
  return new URLSearchParams(body);
}

const server = createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);

    if (req.method === 'GET' && pathname === '/') {
      return send(res, 200, homePage(await loadBooks()));
    }

    if (req.method === 'POST' && pathname === '/add') {
      const form = await readForm(req);
      const title = (form.get('title') ?? '').trim();
      const author = (form.get('author') ?? '').trim();
      if (!title || !author) return send(res, 400, page('Missing fields', '<p>Title and author are required. <a href="/">Back</a></p>'));
      await addBook({ title, author, notes: form.get('notes') });
      return redirect(res, '/');
    }

    const bookMatch = pathname.match(/^\/book\/([\w-]+)$/);
    if (req.method === 'GET' && bookMatch) {
      const book = await getBook(bookMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<p>Book not found. <a href="/">All books</a></p>'));
      return send(res, 200, bookPage(book));
    }

    const finishMatch = pathname.match(/^\/book\/([\w-]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const book = await finishBook(finishMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<p>Book not found. <a href="/">All books</a></p>'));
      return redirect(res, `/book/${book.id}`);
    }

    send(res, 404, page('Not found', '<p>Page not found. <a href="/">All books</a></p>'));
  } catch (err) {
    console.error(err);
    send(res, 500, page('Error', '<p>Something went wrong. <a href="/">All books</a></p>'));
  }
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

