import { test, expect, beforeEach } from 'vitest';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

let store;

beforeEach(async () => {
  process.env.BOOKS_FILE = join(await mkdtemp(join(tmpdir(), 'books-')), 'books.json');
  store = await import(`./store.mjs?cache=${Math.random()}`);
});

test('starts empty when no data file exists', async () => {
  expect(await store.loadBooks()).toEqual([]);
});

test('adds a book and persists it', async () => {
  const book = await store.addBook({ title: ' Dune ', author: 'Frank Herbert', notes: 'sandworms' });
  expect(book.title).toBe('Dune');
  expect(book.finished).toBe(false);
  const books = await store.loadBooks();
  expect(books).toHaveLength(1);
  expect(await store.getBook(book.id)).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'sandworms' });
});

test('marks a book finished', async () => {
  const book = await store.addBook({ title: 'Dune', author: 'Frank Herbert' });
  const finished = await store.finishBook(book.id);
  expect(finished.finished).toBe(true);
  expect(finished.finishedAt).toBeTruthy();
  expect((await store.getBook(book.id)).finished).toBe(true);
});

test('returns null for unknown ids', async () => {
  expect(await store.getBook('nope')).toBeNull();
  expect(await store.finishBook('nope')).toBeNull();
});

